export const SHORT_LABELS=Object.freeze({DOOR_BRACE:'DOOR BRACE',DOOR_REPAIR:'DOOR REPAIR',INTAKE_DIVERSION:'INTAKE',SERVICE_SEAL:'SERVICE SEAL',FILTER_BANK:'FILTERS',LIVE_WIRE:'LIVE WIRE',CHEMICAL_SCRUBBER:'SCRUBBER',EMERGENCY_PURGE:'PURGE',AIR_SUPPLY:'AIR SUPPLY',DEMISTER_DRAINAGE:'DEMISTER'});
const ICON_FILES=Object.freeze({DOOR_BRACE:'door-brace-v1.webp',DOOR_REPAIR:'door-repair-v1.webp',INTAKE_DIVERSION:'intake-diversion-v1.webp',SERVICE_SEAL:'service-seal-v1.webp',FILTER_BANK:'filter-bank-v1.webp',LIVE_WIRE:'live-wire-v1.webp',CHEMICAL_SCRUBBER:'chemical-scrubber-v1.webp',EMERGENCY_PURGE:'emergency-purge-v1.webp',AIR_SUPPLY:'air-supply-v1.webp',DEMISTER_DRAINAGE:'demister-v1.webp'});
// Conditions come from authoritative solver snapshots, independently of occupancy.
export function stationStatuses(v){const stable={DEMISTER_DRAINAGE:!!v.demister?.model.complete,AIR_SUPPLY:!!v.airSupply?.model.complete&&!!v.airSupply?.model.metrics.ready,DOOR_BRACE:v.brace.engaged,DOOR_REPAIR:v.repair.secured===4,INTAKE_DIVERSION:v.intake.complete,SERVICE_SEAL:v.service.complete,FILTER_BANK:v.filter.phase==='CLEAR',LIVE_WIRE:v.liveWire.secured===4,CHEMICAL_SCRUBBER:v.scrubber.phase==='AUTO',EMERGENCY_PURGE:['STABLE','DETERIORATING'].includes(v.purge.operatingState)};
 return Object.fromEntries(Object.keys(SHORT_LABELS).map(id=>[id,{label:SHORT_LABELS[id],available:id!=='EMERGENCY_PURGE'||v.purge.available===true,attentionRequired:(id!=='EMERGENCY_PURGE'||v.purge.available===true)&&!stable[id],stable:(id!=='EMERGENCY_PURGE'||v.purge.available===true)&&!!stable[id],occupiedBy:v.stations[id],state:id==='EMERGENCY_PURGE'&&v.purge.available!==true?'OFFLINE':stable[id]?'STABLE':'NEEDS ATTENTION',reason:id==='EMERGENCY_PURGE'&&v.purge.available!==true?'UPPER RIDGE SERVICE UNAVAILABLE':null}]));}
export function stationOverviewMarkup(){return Object.entries(SHORT_LABELS).map(([id,label])=>`<article id="station-${id}" class="station-card station-pending"><img src="/assets/images/act5/station-icons/${ICON_FILES[id]}" alt="" aria-hidden="true"><span class="status-light" aria-hidden="true"></span><strong>${label}</strong><span id="station-state-${id}">AWAITING STATE</span><small id="station-owner-${id}">UNOCCUPIED</small></article>`).join('');}
export function paintStationOverview(get,statuses){for(const [id,s] of Object.entries(statuses)){const el=get('station-'+id);el.classList.toggle('station-pending',false);el.classList.toggle('needs-attention',s.attentionRequired);el.classList.toggle('station-stable',s.stable);el.classList.toggle('station-offline',s.available===false);el.setAttribute('title',s.reason||s.state);get('station-state-'+id).textContent=s.state;get('station-owner-'+id).textContent=s.available===false?'UPPER RIDGE SERVICE UNAVAILABLE':s.occupiedBy?'● PLAYER '+s.occupiedBy:'UNOCCUPIED';}}
